    "36": {
      "q": "क्या बे वेबसाइट कुकीज़ नि उपयोग खालामो?",
      "a": "माखासे कुकीज़ पेजों खौ हाबा करते रहने थाखाय ज़रूरी हैं। बाक़ी वैकल्पिक दों आरो जब तक नोंथां स्वीकार नङा करते, बंद रहती हैं। नोंथां गासैबो खौ स्वीकार खालामनो हागौ, केवल आवश्यक कुकीज़ रख हानो हागौ, एबा श्रेणी बादियै चुन हानो हागौ, आरो फ़ुटर आव दिए थांबाय \"कुकी सेटिंग्स\" निफ्राय कभी भी अपना मन बदल सकते हैं।"
    },
    "37": {
      "q": "क्या बे वेबसाइट हिंदी आव उपलब्ध दों?",
      "a": "हाँ। नेविगेशन आव दी थांबाय भाषा-स्विच नि उपयोग करें। वेबसाइट खौ दोनों भाषाओं आव हाबा करने थाखाय ही लिखा थांबाय दों, न कि बाद आव सोचकर अनुवाद खालामनाय जाबाय है।"
    }
